WITH account_stats AS (SELECT account_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values, ROUND((100 * SUM(CASE WHEN txn_type = 'DEBIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_debit FROM transactions GROUP BY account_id) SELECT accounts.id, accounts.opened_date, account_stats.merchant_values, account_stats.pct_debit FROM accounts INNER JOIN account_stats ON accounts.id = account_stats.account_id;
